            return char.upper()
        else:
            return char.lower()

    def replace_vowel_with_next_two(char):
        vowels = "aeiouAEIOU"
        for i, vowel in enumerate(vowels):
            if char.lower() == vowel:
                return vowels[(i + 2) % len(vowels)]
        return char

    encoded_message = []
    for char in message:
        if char.isalpha():
            # Swap case
            swapped_char = swap_case(char)
            # Replace vowel with the letter 2 places ahead
            encoded_char = replace_vowel_with_next_two(swapped_char)
            encoded_message.append(encoded_char)
        else:
            # Non-alphabetic characters are added as is
            encoded_message.append(char)

    return ''.join(encoded_message)

