class Solution:
    def maxSlidingWindow(self, arr: List[int], k: int) -> List[int]:
        res = []
        heap = []
        heapq.heapify(heap)
        n = len(arr)

        for i in range(n):
            heapq.heappush(heap, (-arr[i], i))
            if i >= k - 1:
                while heap and heap[0][1] < i - k + 1:
                    heapq.heappop(heap)
                res.append(-heap[0][0])

        return res

```

